head.script:
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gSelectedLdMktTpCd; // 선택된 법인의 시장코드

scwin.gIsurCd;
scwin.gMktTp;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        btn_Delete_3.hide();
        btn_Delete_4.hide();
        txb_Chrg_ISUR_CD.hide();
        txb_LIST_STAT_CD.hide();
        txb_Krx_Emp_EMP_NO.hide();
        txb_Krx_Emp_DEP_CD.hide();
        txb_Chrg3_Chrg_Tp_Cd.hide();
        txb_Chrg3_Discls_Bz_Chrg_Assgn_Dd.hide();
        $c.cm.PanelToGroupBox(panel_1);
        scwin.hideCorpEmpLabels("1"); // 코스닥 숨기기.
        await scwin.setCodes();
        await scwin.getParentValue();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_MARKET_FLAG.setValue(scwin.gLdMktTp);
    if (scwin.gDepCd.substr(0, 2) !== '32') {
        // 코스닥은 공시팀 외에는 전체를 default로 한다. (YSH, 2008/11/05)
        cmb_DEP_CD.setValue(js_dep_cd);
        cmb_EMP_NO.setValue(js_emp_no);
    }
    const ISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD"); // 다른 페이지(기업정보조회)에서 넘어오는 경우 처리.
    // alert(frame.srcUrl);
    txb_ISUR_CD.setValue(ISUR_CD);
    chb_Grp_All.setValue(1); // 처음화면 로딩시 체크박스 전체를 TRUE 로 놓는다.

    // 코스닥은 공시담당보조자 없다. 유가일때만 보이게 한다.(2010.12.15 P.H.J)
    if (scwin.gLdMktTp === '2') {
        panel_8.hide();
        panel_7.style.top = "976";
    }

    // 유가일때는 소속부 항목을 노출시키지 않는다.(2012.03.23 L.D.J)
    if (scwin.gLdMktTp === '1') {
        // 1. 그리드에서 항목 숨기기 및 회사명 항목 width 증가
        $c.cm.setColumnProp(grd_List, "SECT_TP_CD", "Show", false);
        $c.cm.setColumnProp(grd_List, 'COM_ABBRV', 'Width', '220'); // Original Width : 110

        // 2. 회사개요에서 항목 숨기기 및 주요제품 항목 width 증가
        label_115.hide();
        txb_SECT_TP_CD.hide();
        // txb_Corp_MAJ_PROD_NM.style.width= "525px"; //Original Width : 200

        // 3. 엑셀다운로드 그리드에서 항목 제외
        $c.cm.setColumnProp(grd_List2, "SECT_TP_CD", "Show", false);
        $c.cm.setColumnProp(grd_List2, "PHARMA_BIO_COM_YN", "Show", false);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_CorpInfo_onclick
 * @description 「회사정보」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_CorpInfo_onclick = async function() {
    try {
        if (txb_Corp_COM_NM.getValue() === "") {
            await $c.win.alert("회사를 선택하여 주십시오");
        } else {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601.btn_CorpInfo_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        await scwin.readChargeIssue(grd_List, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name rdo_MARKET_FLAG_onselchange
 * @description rdo_MARKET_FLAG onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MARKET_FLAG_onselchange = function() {
    try {
        scwin.hideCorpEmpLabels(rdo_MARKET_FLAG.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601.rdo_MARKET_FLAG_onselchange" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        dts_EMP_NO.sort("DEP_CD", 0);
        // dts_EMP_NO.sort(); // W-Craft 주석처리
        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        const vVal = cmb_DEP_CD.getValue();
        if (vVal === "") {
            // 전체일 경우
            return true;
        } else {
            const vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
            if (vVal2 === "") return true; // 전체.
            return (vVal === vVal2) ? true : false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = async function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        await scwin.readChargeIssue(grd_List, 1, "ISUR_CD");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601.dts_Grid_OnLoadCompleted" });
    }
};

