    try {
        if (js_market === "1" && rowcount > 0) {
            txb_Chrg1_EDU_COMPLT_DD.setValue(dts_Charge1_Info.getCellData(1, "EDU_COMPLT_DD_ETC")); // 책임자과정,담당자 과정 주식연수시기
            txb_Chrg1_EDU_CRS_NM.setValue(dts_Charge1_Info.getCellData(1, "EDU_COMPLT_YN_ETC")); // 책임자과정. 담당자 과정 주식연수과정 이수여부

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601.dts_Charge1_Info_OnLoadCompleted" });
    }
};

