/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (grd_List2.getRowCount() < 1) {
            await $c.win.alert("저장할 정보가 없습니다.");
        } else {
            $c.stf.doLogSave("ULDSTF30601.xml", SCREN_PROCS_TP_CD_07, '');
            $c.data.downloadGridViewExcel(grd_List2, {fileName: "담당종목목록", type: "8"});
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601.btn_Excel_onclick" });
    }
};

