        id : "sbm_dts_Charge3_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge3_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시대리인(유)
    const sbmOptions6 = {
