/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    const arr = url.split("?");

    // alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getParentValue = async function() {
    const pvd = scwin.getProvider();
    if (pvd !== null) {
        scwin.gMktTp = pvd.scwin.gMktTp;
        scwin.gIsurCd = pvd.scwin.gIsurCd;
        if ($c.ut.trim(scwin.gIsurCd).length === 5) {
            await scwin.initSearch();
        }
    }
};

/**
 * @method
 * @name initSearch
 * @description 다른창에서 담당종목 조회를 클릭할때
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    await scwin.getChargeIssue(scwin.gIsurCd, scwin.gMktTp);
};

/**
 * @method
 * @name readChargeIssue
 * @description read Charge Issue 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readChargeIssue = async function(GridID, row, colid) {
    if (row < 1) return;
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    scwin.gIsurCd = vISUR_CD; // 회사정보 팝업때문에
    const vMKT_TP_CD = objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    scwin.gSelectedLdMktTpCd = vMKT_TP_CD; // 20180802

    await scwin.getChargeIssue(vISUR_CD, vMKT_TP_CD);
};

/**
 * @method
 * @name hideCorpEmpLabels
 * @description hide Corp Emp Labels 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.hideCorpEmpLabels = function(flag) {
    const vStockLabels = new Array(lbl_CorpEmp2, lbl_CorpEmp3);
    const vKosdaqLabels = new Array(lbl_CorpEmp2_1, lbl_CorpEmp3_1);
    // 유가는 초기값을 가지고 있으므로 위치 이동은 없다.
    if (flag === "1") {
        // 유가. => 코스닥 숨기고 유가 위치이동 및 보이기.

        for (let i = 0; i < vKosdaqLabels.length; i++) {
            vKosdaqLabels[i].hide();
            vStockLabels[i].show("");
        }
    } else if (flag === "2" || flag === "6") {
        // 코스닥.=>유가를 숨기고 코스닥 위치이동 및 보이기
        for (let i = 0; i < vStockLabels.length; i++) {
            $c.stf.SetWindowPos(vKosdaqLabels[i], vStockLabels[i].style.top, vStockLabels[i].style.left, vStockLabels[i].style.getStyle("width"), vStockLabels[i].style.getStyle("height"));
            $p.getComponentById(vStockLabels[i]).hide();
            vKosdaqLabels[i].show("");
        }
    }
};

