/**
 * @method
 * @name changeFormat
 * @description change Format 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeFormat = function() {
    const ar = new Array(txb_Corp_RGHT_LIST_DD, txb_Chrg1_EDU_COMPLT_DD, txb_Chrg1_CHRG_DESIGN_DD, txb_Chrg1_WORK_TM, txb_Chrg2_WORK_TM, txb_Chrg3_WORK_TM, txb_Chrg2_EDU_COMPLT_DD, txb_Chrg2_CHRG_DESIGN_DD, txb_Chrg3_EDU_COMPLT_DD, txb_Chrg3_CHRG_DESIGN_DD);
    for (let i = 0; i < ar.length; i++) {
        const bfVal = ar[i].getValue();
        if (bfVal !== "") {
            const afVal = $c.stf.FormatDateEx(bfVal);
            ar[i].setValue(afVal);
        }
    }
};

