 */
scwin.openResume = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF30612", "/issueinfo/ULDSTF30612.gfm", "이력조회", 20, 20, 1270, 780, "");
};

/**
 * @method
 * @name FormatDateEx
 * @description Format Date Ex 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.FormatDateEx = function(str) {
    if (str === "") return "";
    return str.substring(0, 4) + "-" + str.substring(4, 6) + "-" + str.substring(6, 8);
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs, chb_Grp_If];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
